#!/usr/bin/env bash
# Evernight HSR ASCII animation - standalone build
# All animation frames are embedded below; no external files are required.
set -euo pipefail

FRAME_DELAY="${FRAME_DELAY:-0.125}"
TMP_DIR="$(mktemp -d "${TMPDIR:-/tmp}/evernight_hsr.XXXXXX")"
cleanup() {
    rm -rf "$TMP_DIR"
}
trap cleanup EXIT INT TERM

# Decode the embedded frame archive into a temporary directory.
awk '/^__EVERNIGHT_PAYLOAD_BELOW__$/ { found=1; next } found' "$0" \
    | base64 --decode \
    | tar -xzf - -C "$TMP_DIR"

shopt -s nullglob
frames=("$TMP_DIR"/frames/*.txt)
if ((${#frames[@]} == 0)); then
    echo "Error: no animation frames found." >&2
    exit 1
fi

while true; do
    for frame in "${frames[@]}"; do
        clear
        cat "$frame"
        sleep "$FRAME_DELAY"
    done
done

